package com.bautruc.ecommerce.order.api;
import java.time.LocalDate;import com.bautruc.ecommerce.common.logging.LogContext;import com.bautruc.ecommerce.common.response.*;import com.bautruc.ecommerce.common.time.BusinessClock;import com.bautruc.ecommerce.order.api.request.UpdateOrderStatusRequest;import com.bautruc.ecommerce.order.api.response.*;import com.bautruc.ecommerce.order.application.*;import com.bautruc.ecommerce.order.domain.*;import com.bautruc.ecommerce.payment.domain.PaymentStatus;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;
@RestController public class AdminOrderController{private final OrderQueryService queries;private final OrderCommandService commands;private final BusinessClock clock;public AdminOrderController(OrderQueryService q,OrderCommandService c,BusinessClock b){queries=q;commands=c;clock=b;}@GetMapping("/api/v1/admin/orders")public ApiResponse<PageResponse<OrderSummaryResponse>>list(@RequestParam(required=false)String keyword,@RequestParam(required=false)OrderStatus orderStatus,@RequestParam(required=false)PaymentStatus paymentStatus,@RequestParam(required=false)LocalDate fromDate,@RequestParam(required=false)LocalDate toDate,@RequestParam(required=false)Integer page,@RequestParam(required=false)Integer size,@RequestParam(required=false)String sort){return ok(PageResponse.from(queries.adminList(keyword,orderStatus,paymentStatus,fromDate,toDate,page,size,sort)));}@GetMapping("/api/v1/admin/orders/{id}")public ApiResponse<OrderDetailResponse>detail(@PathVariable Long id){return ok(queries.adminDetail(id));}@PatchMapping("/api/v1/admin/orders/{id}/status")public ApiResponse<OrderDetailResponse>transition(@PathVariable Long id,@Valid @RequestBody UpdateOrderStatusRequest r){commands.transition(id,r.status());return ok(queries.adminDetail(id));}private <T>ApiResponse<T>ok(T d){return ApiResponse.success(d,null,clock.businessNow().toOffsetDateTime(),LogContext.currentCorrelationId());}}
